            visited[r][c] = True
            dfs(r-1, c)
            dfs(r+1, c)
            dfs(r, c-1)
            dfs(r, c+1)

    for r in range(rows):
        for c in range(cols):
            if g[r][c] == '1' and not visited[r][c]:
                count += 1
                dfs(r, c)

    return count
